interface usb20_if (
    input logic clk_i,
    input logic rst_ni
);

  // DUT'S input signals (injected by the Driver / Testbench)
  logic cio_usb_dp_i;
  logic cio_usb_dn_i;
  logic cio_sense_i;

  // Out signals from the DUT (generated by USB chip)
  logic cio_usb_dp_o;
  logic cio_usb_dn_o;

  // Signals of output enabling (generated by USB chip)
  logic cio_usb_dp_en_o;
  logic cio_usb_dn_en_o;
  logic cio_usb_oe_o;

  // Always-On observation signals
  logic usb_dp_pullup_en_o;
  logic usb_dn_pullup_en_o;
  logic wake_req_aon_o;

endinterface : usb20_if
